function parseBundle(raw) {
  if (!raw) return {};
  if (raw.data) {
    try {
      return typeof raw.data === 'string' ? JSON.parse(raw.data) : raw.data;
    } catch (e) {
      return raw;
    }
  }
  if (typeof raw === 'string') {
    try { return JSON.parse(raw); } catch (e) { return {}; }
  }
  return raw;
}

const encBundle = parseBundle($('Fetch Encounters').first()?.json);
const medBundle = parseBundle($('Fetch MedicationRequests').first()?.json);
const srvBundle = parseBundle($('Fetch ServiceRequests').first()?.json);

// Collect all entries across encBundle (revincludes), medBundle, srvBundle
const allEntries = [
  ...(encBundle.entry || []),
  ...(medBundle.entry || []),
  ...(srvBundle.entry || [])
];

const medRequests = [];
const seenMeds = new Set();
for (const e of allEntries) {
  const r = e.resource;
  if (!r || r.resourceType !== 'MedicationRequest') continue;
  if (seenMeds.has(r.id)) continue;
  seenMeds.add(r.id);

  const patientRef = r.subject?.reference || '';
  const patientUuid = patientRef.replace(/^Patient\//, '');
  const encRef = r.encounter?.reference || '';
  const encounterUuid = encRef.replace(/^Encounter\//, '');
  const medName = r.medicationReference?.display || 'Prescribed Medication';
  const qty = r.dispenseRequest?.quantity?.value || 1;

  let code = 'DRUG-PARA500';
  let price = 5.0;
  if (medName.toLowerCase().includes('amoxicillin')) {
    code = 'DRUG-AMOX250';
    price = 12.0;
  }

  medRequests.push({
    med_order_uuid: r.id,
    patient_uuid: patientUuid,
    encounter_uuid: encounterUuid,
    medication_name: medName,
    quantity: qty,
    product_code: code,
    unit_price: price
  });
}

const serviceRequests = [];
const seenSrvs = new Set();
for (const e of allEntries) {
  const r = e.resource;
  if (!r || r.resourceType !== 'ServiceRequest') continue;
  if (seenSrvs.has(r.id)) continue;
  seenSrvs.add(r.id);

  const patientRef = r.subject?.reference || '';
  const patientUuid = patientRef.replace(/^Patient\//, '');
  const encRef = r.encounter?.reference || '';
  const encounterUuid = encRef.replace(/^Encounter\//, '');
  const srvName = r.code?.text || r.code?.coding?.[0]?.display || 'Lab Test';

  let code = 'LAB-FBC';
  let price = 35.0;
  if (srvName.toLowerCase().includes('chest') || srvName.toLowerCase().includes('x-ray')) {
    code = 'RAD-XRAY-CHEST';
    price = 75.0;
  }

  serviceRequests.push({
    service_order_uuid: r.id,
    patient_uuid: patientUuid,
    encounter_uuid: encounterUuid,
    service_name: srvName,
    product_code: code,
    unit_price: price
  });
}

const encounters = [];
const now = new Date();

for (const e of (encBundle.entry || [])) {
  const r = e.resource;
  if (!r || r.resourceType !== 'Encounter') continue;

  // Skip facility visit wrappers
  const isVisitTag = (r.meta?.tag || []).some(t => t.code === 'visit');
  if (isVisitTag) continue;

  const patientRef = r.subject?.reference || '';
  const patientUuid = patientRef.replace(/^Patient\//, '');

  const matchingMeds = medRequests.filter(m => m.encounter_uuid === r.id);
  const matchingServices = serviceRequests.filter(s => s.encounter_uuid === r.id);

  // Dynamic date check: within 7 days
  let isRecent = false;
  if (r.period?.start) {
    const d = new Date(r.period.start);
    if (!isNaN(d.getTime())) {
      isRecent = (now.getTime() - d.getTime()) < (7 * 24 * 3600 * 1000);
    }
  }

  // Check if Inpatient encounter
  const classCode = (r.class?.code || '').toUpperCase();
  const typeText = (r.type || []).map(t => t.text || t.coding?.[0]?.display || '').join(' ').toLowerCase();
  const isInpatient = classCode.includes('IMP') || typeText.includes('inpatient') || typeText.includes('admission');
  const isConsultation = typeText.includes('consult') || classCode.includes('AMB') || (r.type || []).some(t => t.coding?.[0]?.code === 'dd528487-82a5-4082-9c72-ed246bd49591');

  if (matchingMeds.length > 0 || matchingServices.length > 0 || isInpatient || (isConsultation && isRecent)) {
    encounters.push({
      encounter_uuid: r.id,
      patient_uuid: patientUuid,
      consultation_code: 'CONS-GEN',
      consultation_fee: 50.0,
      is_inpatient: isInpatient,
      inpatient_code: isInpatient ? 'INP-BED' : null,
      inpatient_fee: isInpatient ? 100.0 : 0.0,
      medications: matchingMeds,
      services: matchingServices
    });
  }
}

return [{
  json: {
    medication_orders: medRequests,
    service_orders: serviceRequests,
    billable_encounters: encounters
  }
}];

