return $input.all().map((item, idx) => {
  const evalItem = $('Evaluate Picking Existence').all()[idx]?.json || {};
  const prodRaw = $('Lookup Product & Stock in Odoo').all()[idx]?.json || {};
  const prodInfo = Array.isArray(prodRaw) ? prodRaw[0] : prodRaw;
  const pickingResp = $('Create Delivery Order (stock.picking)').all()[idx]?.json;
  const pickingId = Array.isArray(pickingResp) ? pickingResp[0] : (typeof pickingResp === 'number' ? pickingResp : null);

  const preQty = prodInfo.qty_available || 0;
  const dispensedQty = evalItem.quantity || 1;
  const postQty = preQty - dispensedQty;

  return {
    json: {
      status: 'DISPENSED',
      picking_id: pickingId,
      med_order_uuid: evalItem.med_order_uuid,
      product_id: prodInfo.id || 56,
      product_code: evalItem.product_code,
      dispensed_qty: dispensedQty,
      remaining_qty: postQty,
      buffer_threshold: 50,
      needs_reorder: postQty < 50
    }
  };
});

const data = $('Correlate Clinical Orders & Encounters').first().json;
const encounters = data.billable_encounters || [];

return encounters.map(enc => ({
  json: {
    task_type: 'encounter_invoice',
    encounter_uuid: enc.encounter_uuid,
    patient_uuid: enc.patient_uuid,
    invoice_ref: `OPENMRS-ENC-${enc.encounter_uuid}`,
    consultation_code: enc.consultation_code,
    consultation_fee: enc.consultation_fee,
    is_inpatient: enc.is_inpatient,
    inpatient_code: enc.inpatient_code,
    inpatient_fee: enc.inpatient_fee,
    medications: enc.medications,
    services: enc.services
  }
}));

const items = $input.all();
const tasks = $('Split Encounter Invoice Tasks').all();

return items.map((item, idx) => {
  const resp = item.json;
  const searchResult = resp.body !== undefined ? resp.body : resp;
  const task = tasks[idx]?.json || {};

  let exists = false;
  let invoiceId = null;

  if (Array.isArray(searchResult) && searchResult.length > 0) {
    exists = true;
    invoiceId = searchResult[0].id;
  }

  return {
    json: {
      ...task,
      invoice_already_exists: exists,
      existing_invoice_id: invoiceId
    }
  };
});

const invoiceTasks = $('Evaluate Invoice Existence').all();
const partners = $('Lookup Patient Partner for Invoice').all();
const catalogs = $input.all();

const results = [];

catalogs.forEach((catItem, idx) => {
  const task = invoiceTasks[idx]?.json || {};
  const rawPartner = partners[idx]?.json;
  const partnerList = rawPartner && rawPartner.body !== undefined ? rawPartner.body : rawPartner;
  const rawCatalog = catItem.json;
  const productCatalog = rawCatalog && rawCatalog.body !== undefined ? rawCatalog.body : rawCatalog;

  if (!Array.isArray(partnerList) || partnerList.length === 0) {
    // Partner not found yet in Odoo - skip this encounter until synced
    return;
  }
  const partnerId = partnerList[0].id;

  const prodMap = {};
  if (Array.isArray(productCatalog)) {
    for (const p of productCatalog) {
      prodMap[p.default_code] = p;
    }
  }

  const invoiceLines = [];

  // 1. General Consultation line
  const consProd = prodMap['CONS-GEN'];
  invoiceLines.push([0, 0, {
    product_id: consProd ? consProd.id : false,
    name: 'General Consultation Fee',
    quantity: 1,
    price_unit: consProd ? consProd.list_price : 50.0
  }]);

  // 2. Inpatient Bed Fee (if inpatient)
  if (task.is_inpatient) {
    const inpProd = prodMap['INP-BED'];
    invoiceLines.push([0, 0, {
      product_id: inpProd ? inpProd.id : false,
      name: 'Inpatient Daily Bed / Admission Fee',
      quantity: 1,
      price_unit: inpProd ? inpProd.list_price : 100.0
    }]);
  }

  // 3. Services (Lab tests)
  for (const s of task.services || []) {
    const sProd = prodMap[s.product_code];
    invoiceLines.push([0, 0, {
      product_id: sProd ? sProd.id : false,
      name: s.service_name,
      quantity: 1,
      price_unit: sProd ? sProd.list_price : s.unit_price
    }]);
  }

  // 4. Medications
  for (const m of task.medications || []) {
    const mProd = prodMap[m.product_code];
    invoiceLines.push([0, 0, {
      product_id: mProd ? mProd.id : false,
      name: m.medication_name,
      quantity: m.quantity,
      price_unit: mProd ? mProd.list_price : m.unit_price
    }]);
  }

  results.push({
    json: {
      move_type: 'out_invoice',
      partner_id: partnerId,
      ref: task.invoice_ref,
      encounter_uuid: task.encounter_uuid,
      patient_uuid: task.patient_uuid,
      invoice_lines: invoiceLines
    }
  });
});

return results;

return $input.all().map((item, idx) => {
  const invoiceResp = item.json;
  const invoiceId = Array.isArray(invoiceResp) ? invoiceResp[0] : (typeof invoiceResp === 'number' ? invoiceResp : null);
  const constructItem = $('Construct Draft Customer Invoice').all()[idx]?.json || {};

  return {
    json: {
      status: 'INVOICE_CREATED',
      account_move_id: invoiceId,
      invoice_ref: constructItem.ref,
      encounter_uuid: constructItem.encounter_uuid,
      patient_uuid: constructItem.patient_uuid,
      timestamp: new Date().toISOString()
    }
