});

const items = $input.all();
if (!items || items.length === 0) return [];

function parseBundle(raw) {
  if (!raw) return {};
  if (raw.data) {
    try {
      return typeof raw.data === 'string' ? JSON.parse(raw.data) : raw.data;
    } catch (e) {
      return raw;
    }
  }
  if (typeof raw === 'string') {
    try { return JSON.parse(raw); } catch (e) { return {}; }
  }
  return raw;
}

const encBundle = parseBundle($('Fetch Encounters').first()?.json);
const encToPatient = {};
for (const e of (encBundle.entry || [])) {
  const r = e.resource;
  if (!r || r.resourceType !== 'Encounter') continue;
  const pRef = r.subject?.reference || '';
  const pUuid = pRef.replace(/^Patient\//, '');
  if (r.id && pUuid) {
    encToPatient[r.id] = pUuid;
  }
}

const results = [];
for (const item of items) {
  const inv = item.json;
  if (!inv || !inv.id) continue;
  const encUuid = (inv.ref || '').replace(/^OPENMRS-ENC-/, '');
  const patUuid = encToPatient[encUuid] || null;
  results.push({
    json: {
      invoice_id: inv.id,
      invoice_name: inv.name,
      payment_state: inv.payment_state,
      encounter_uuid: encUuid,
      patient_uuid: patUuid,
      cleared_at: new Date().toISOString()
    }
  });
}
return results;

return $input.all().map((item, idx) => {
  const paidEnc = $('Extract Paid Encounters').all()[idx]?.json || {};
  return {
    json: {
      status: 'CLEARANCE_TAGGED',
      invoice_id: paidEnc.invoice_id,
      invoice_name: paidEnc.invoice_name,
      encounter_uuid: paidEnc.encounter_uuid,
      patient_uuid: paidEnc.patient_uuid,
      payment_state: paidEnc.payment_state,
      clinical_clearance: 'Payment Settled: Financially Cleared in OpenMRS',
      timestamp: paidEnc.cleared_at
    }
  };
});

