function extractResults(raw) {
  if (!raw) return [];
  if (Array.isArray(raw.results)) return raw.results;
  if (Array.isArray(raw)) return raw;
  if (raw.body) {
    if (Array.isArray(raw.body.results)) return raw.body.results;
    if (typeof raw.body === 'string') {
      try {
        const parsed = JSON.parse(raw.body);
        if (Array.isArray(parsed.results)) return parsed.results;
        if (Array.isArray(parsed)) return parsed;
      } catch (e) {}
    }
  }
  if (raw.data) {
    if (Array.isArray(raw.data.results)) return raw.data.results;
    if (typeof raw.data === 'string') {
      try {
        const parsed = JSON.parse(raw.data);
        if (Array.isArray(parsed.results)) return parsed.results;
        if (Array.isArray(parsed)) return parsed;
      } catch (e) {}
    }
  }
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed.results)) return parsed.results;
      if (Array.isArray(parsed)) return parsed;
    } catch (e) {}
  }
  return [];
}

const obsResults = $input.all();
const paidEncs = $('Extract Paid Encounters').all();

const uncleared = [];
obsResults.forEach((item, idx) => {
  const obsData = item.json;
  const results = extractResults(obsData);
  const paidEnc = paidEncs[idx]?.json || {};

  // If no observation exists and we have valid encounter_uuid and patient_uuid:
  if (results.length === 0 && paidEnc.encounter_uuid && paidEnc.patient_uuid) {
    uncleared.push({
      json: paidEnc
    });
  }
});

return uncleared;
